def forwards(apps, schema_editor):
    """App admins become admins; committee heads get the matching wing permissions; core-committee
    members get them for all wings (the powers they had before)."""
    Member = apps.get_model("org", "Member")
    Membership = apps.get_model("org", "Membership")
    Grant = apps.get_model("org", "Grant")
    Member.objects.filter(is_admin=True).update(level="admin")
    lead = ["tasks", "responsibilities", "announcements", "meetings"]
    for ms in Membership.objects.filter(role="head").select_related("committee"):
        for perm in lead + ["people"]:
            g, _ = Grant.objects.get_or_create(member_id=ms.member_id, perm=perm)
            if ms.committee.is_core:
                g.all_wings = True
                g.save()
    for ms in Membership.objects.filter(committee__is_core=True, role="member"):
        for perm in lead:
            Grant.objects.update_or_create(member_id=ms.member_id, perm=perm, defaults={"all_wings": True})


